#![allow(unused_imports)]
use vstd::prelude::*;

verus! {
    /// Given an integer `n` in the range 1..=999, returns the correct
    /// pronunciation suffix as a `Vec<char>` ending with a newline:
    ///
    ///   - ones digit ∈ {2,4,5,7,9} → "hon\n"
    ///   - ones digit ∈ {0,1,6,8} → "pon\n"
    ///   - ones digit == 3       → "bon\n"
    pub fn solve(n: i8) -> Vec<char>
        requires 1 <= n && n <= 999
        ensures
            if n % 10 == 3 {
                ret == vec!['b','o','n','\n']
            } else if
                n % 10 == 2 || n % 10 == 4 ||
                n % 10 == 5 || n % 10 == 7 ||
                n % 10 == 9
            {
                ret == vec!['h','o','n','\n']
            } else {
                // covers {0,1,6,8}
                ret == vec!['p','o','n','\n']
            }
    {
        // Compute the ones‐digit. Since n ≥ 1, this is non‐negative.
        let ones = n % 10;
        if ones == 3 {
            vec!['b', 'o', 'n', '\n']
        } else if
            ones == 2 || ones == 4 ||
            ones == 5 || ones == 7 ||
            ones == 9
        {
            vec!['h', 'o', 'n', '\n']
        } else {
            vec!['p', 'o', 'n', '\n']
        }
    }
}